var UserTier = /* @__PURE__ */ function(UserTier) {
	UserTier[UserTier["FREE"] = 1] = "FREE";
	UserTier[UserTier["EPHEMERAL"] = 2] = "EPHEMERAL";
	UserTier[UserTier["PRO"] = 3] = "PRO";
	return UserTier;
}({});
